+        {isVideoReady && videoRef.current ? (
+          <KonvaImage
+            ref={imageRef}
+            image={videoRef.current}
+            width={width}
+            height={height}
+          />
+        ) : posterImage ? (
+          // Show poster image while video loads
+          <KonvaImage
+            ref={imageRef}
+            image={posterImage}
+            width={width}
+            height={height}
+          />
+        ) : (
+          // Fallback placeholder if no poster
