diff --git a/app/api/video/register/route.ts b/app/api/video/register/route.ts
new file mode 100644
index 0000000..ed0449d
--- /dev/null
+++ b/app/api/video/register/route.ts
@@ -0,0 +1,198 @@
+import { NextRequest, NextResponse } from 'next/server';
+import { z } from 'zod';
+
+import { createVideo } from '@/actions/video';
+import createLogger from '@/lib/logger';
+import { currentOrGuestUserId } from '@/lib/auth';
+import { ERROR_IDS } from '@/constants/errorIds';
+import { getVideoUrlAndPreview } from '@/data/video';
+
+const logger = createLogger('api-video-register');
+
+/**
+ * POST /api/video/register
+ *
+ * Registers an uploaded video in the database.
+ * This endpoint is called after a client has successfully uploaded a video
+ * directly to S3 using a presigned URL.
+ *
+ * Authentication:
+ * - Requires authenticated user or guest session
+ * - Validates that objectKey belongs to the requesting user
+ * - Returns 401 if no valid session
+ * - Returns 403 if trying to register another user's file
+ *
+ * Workflow:
+ * 1. Validates request body against schema
+ * 2. Verifies user owns the S3 object
+ * 3. Creates Video record in database with metadata
+ * 4. Returns video URL and poster URL (generated by Lambda)
+ *
+ * Request Body:
+ * @param objectKey - Required. S3 object key (format: videos/userId/uuid/output.mp4)
+ * @param fileName - Optional. Original filename
+ * @param mimeType - Optional. MIME type (defaults to 'video/mp4')
+ * @param width - Optional. Video width in pixels
+ * @param height - Optional. Video height in pixels
+ * @param duration - Optional. Video duration in seconds
+ * @param fileSize - Optional. File size in bytes
+ *
+ * @returns Video record containing:
+ *   - id: Database ID of created Video record
+ *   - objectKey: S3 object key for retrieving the video
+ *   - url: Signed URL for video playback
+ *   - posterUrl: Signed URL for poster image (Lambda-generated)
+ */
+
+// Zod schema for request validation
+const registerVideoSchema = z.object({
+  objectKey: z
+    .string()
+    .min(1, 'objectKey is required')
+    .regex(
+      /^videos\/[a-zA-Z0-9-]+\/[a-zA-Z0-9-]+\/[a-zA-Z0-9._-]+\.(mp4|webm|mov|avi|mkv)$/i,
+      'Invalid objectKey format. Must be: videos/userId/identifier/filename.ext'
+    ),
+  fileName: z.string().optional(),
+  mimeType: z
+    .string()
+    .regex(
+      /^video\/(mp4|webm|quicktime|x-msvideo|x-matroska)$/i,
+      'Invalid mimeType. Must be video/mp4, video/webm, video/quicktime, video/x-msvideo, or video/x-matroska'
+    )
+    .optional(),
+  width: z.number().positive().int().optional(),
+  height: z.number().positive().int().optional(),
+  duration: z.number().positive().optional(),
+  fileSize: z
+    .number()
+    .positive()
+    .int()
+    .max(500 * 1024 * 1024, 'File size exceeds maximum allowed size of 500MB')
+    .optional()
+});
+
+export async function POST(request: NextRequest) {
+  let requestBody: unknown;
+
+  try {
+    // 1. Authentication check
+    const userId = await currentOrGuestUserId();
+    if (!userId) {
+      logger.warn('Unauthorized video registration attempt');
+      return NextResponse.json(
+        { error: 'Unauthorized. Please sign in.' },
+        { status: 401 }
+      );
+    }
+
+    // 2. Parse and validate request body
+    requestBody = await request.json();
+    const validation = registerVideoSchema.safeParse(requestBody);
+
+    if (!validation.success) {
+      logger.warn('Invalid video registration request', {
+        userId,
+        errors: validation.error.flatten()
+      });
+      return NextResponse.json(
+        {
+          error: 'Invalid request data',
+          details: validation.error.flatten().fieldErrors
+        },
+        { status: 400 }
+      );
+    }
+
+    const { objectKey, fileName, mimeType, width, height, duration, fileSize } =
+      validation.data;
+
+    // 3. Verify object ownership
+    // Extract userId from objectKey (format: videos/userId/identifier/filename.ext)
+    const keyParts = objectKey.split('/');
+    const keyUserId = keyParts[1];
+
+    if (keyUserId !== userId) {
+      logger.error("Unauthorized attempt to register another user's video", {
+        errorId: ERROR_IDS.IMAGE_REGISTER_OWNERSHIP_VIOLATION,
+        requestingUserId: userId,
+        objectKeyUserId: keyUserId,
+        objectKey
+      });
+      return NextResponse.json(
+        {
+          error:
+            'Unauthorized. Cannot register videos belonging to other users.'
+        },
+        { status: 403 }
+      );
+    }
+
+    // 4. Create video record in database
+    const video = await createVideo({
+      objectKey,
+      fileName: fileName || objectKey.split('/').pop(),
+      mimeType: mimeType || 'video/mp4',
+      userId,
+      width: width ?? null,
+      height: height ?? null,
+      duration: duration ?? null,
+      fileSize: fileSize ? BigInt(fileSize) : null
+    });
+
+    logger.info('Video registered successfully', {
+      videoId: video.id,
+      objectKey,
+      userId
+    });
+
+    // 5. Get signed URLs for video and poster
+    const { url, previewImage } = await getVideoUrlAndPreview(objectKey);
+
+    return NextResponse.json({
+      id: video.id,
+      objectKey: video.objectKey,
+      fileName: video.fileName,
+      mimeType: video.mimeType,
+      width: video.width,
+      height: video.height,
+      duration: video.duration,
+      fileSize: video.fileSize ? Number(video.fileSize) : null,
+      url,
+      posterUrl: previewImage?.url ?? null
+    });
+  } catch (error) {
+    logger.error(
+      'Failed to register video in database',
+      error instanceof Error ? error : { cause: String(error) },
+      {
+        errorId: ERROR_IDS.IMAGE_REGISTER_DB_ERROR,
+        errorName:
+          error instanceof Error ? error.constructor.name : typeof error,
+        stack: error instanceof Error ? error.stack : undefined,
+        context: {
+          objectKey:
+            requestBody &&
+            typeof requestBody === 'object' &&
+            'objectKey' in requestBody
+              ? String(requestBody.objectKey)
+              : 'not-parsed',
+          requestUrl: request.url,
+          requestMethod: request.method
+        }
+      }
+    );
+
+    const statusCode =
+      error instanceof Error && error.message.includes('validation')
+        ? 400
+        : 500;
+
+    const errorMessage =
+      error instanceof Error && error.message.includes('validation')
+        ? 'Invalid video data provided'
+        : 'Failed to register video. Please try again or contact support if the issue persists.';
+
+    return NextResponse.json({ error: errorMessage }, { status: statusCode });
+  }
+}
diff --git a/app/api/videos/src/route.ts b/app/api/videos/src/route.ts
new file mode 100644
index 0000000..9c06547
--- /dev/null
+++ b/app/api/videos/src/route.ts
@@ -0,0 +1,87 @@
+import { NextRequest, NextResponse } from 'next/server';
+
+import { currentUser } from '@/lib/auth';
+import createLogger from '@/lib/logger';
+import { getVideosByIdsForUser, getVideoUrlAndPreview } from '@/data/video';
+
+const logger = createLogger('api-videos-src');
+
+/**
+ * GET /api/videos/src
+ *
+ * Fetches signed URLs for videos by their database IDs.
+ * Used by the canvas to restore video URLs when loading a saved draft.
+ *
+ * Query Parameters:
+ * @param ids - Comma-separated list of video IDs
+ *
+ * @returns Array of { id, url, posterUrl } objects
+ */
+export async function GET(request: NextRequest) {
+  // Authenticate user - only logged-in users can fetch video URLs
+  const user = await currentUser();
+  if (!user?.id) {
+    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
+  }
+
+  const searchParams = request.nextUrl.searchParams;
+  const idsParam = searchParams.get('ids');
+
+  if (!idsParam) {
+    return NextResponse.json({ error: 'Missing video IDs' }, { status: 400 });
+  }
+
+  const videoIds = idsParam.split(',').filter(Boolean);
+
+  if (videoIds.length === 0) {
+    return NextResponse.json(
+      { error: 'No video IDs provided' },
+      { status: 400 }
+    );
+  }
+
+  try {
+    // Fetch videos from database (filtered by user ownership)
+    const videos = await getVideosByIdsForUser(videoIds, user.id);
+
+    // Get signed URLs for each video
+    const videoUrls = await Promise.all(
+      videos.map(async (video) => {
+        try {
+          const { url, previewImage } = await getVideoUrlAndPreview(
+            video.objectKey
+          );
+          return {
+            id: video.id,
+            url,
+            posterUrl: previewImage?.url ?? null
+          };
+        } catch (error) {
+          logger.warn(`Failed to get URLs for video ${video.id}:`, { error });
+          return {
+            id: video.id,
+            url: null,
+            posterUrl: null
+          };
+        }
+      })
+    );
+
+    // Return in same order as requested IDs, with nulls for not found
+    const result = videoIds.map((id) => {
+      const found = videoUrls.find((v) => v.id === id);
+      return found || { id, url: null, posterUrl: null };
+    });
+
+    return NextResponse.json(result);
+  } catch (error) {
+    logger.error(
+      'Error fetching video URLs:',
+      error instanceof Error ? error : { cause: String(error) }
+    );
+    return NextResponse.json(
+      { error: 'Failed to fetch videos' },
+      { status: 500 }
+    );
+  }
+}
