+
+    if (!layer || !isVideoReady) return;
+
+    if (isPlaying) {
+      // Start animation loop to redraw video frames
+      if (!animationRef.current) {
+        animationRef.current = new Konva.Animation(() => {
+          // Animation callback triggers layer redraw
+        }, layer);
+      }
+      animationRef.current.start();
+    } else {
+      animationRef.current?.stop();
+    }
+
+    return () => {
+      animationRef.current?.stop();
+    };
+  }, [isPlaying, isVideoReady]);
+
+  // Update video properties when they change
+  useEffect(() => {
+    if (videoRef.current) {
+      videoRef.current.volume = volume ?? 1;
+      videoRef.current.muted = isMuted ?? false;
+      videoRef.current.loop = loop ?? false;
+    }
+  }, [volume, isMuted, loop]);
+
+  // Shift key handling for constrained drag
+  useEffect(() => {
+    const handleKeyDown = (e: KeyboardEvent) => {
+      if (e.key === 'Shift') setIsShiftPressed(true);
+    };
+    const handleKeyUp = (e: KeyboardEvent) => {
+      if (e.key === 'Shift') setIsShiftPressed(false);
+    };
+    window.addEventListener('keydown', handleKeyDown);
+    window.addEventListener('keyup', handleKeyUp);
+    return () => {
+      window.removeEventListener('keydown', handleKeyDown);
+      window.removeEventListener('keyup', handleKeyUp);
+    };
+  }, []);
+
+  // Attach transformer
+  useEffect(() => {
+    if (!showTransformer || !transformerRef.current || !groupRef.current) {
+      return;
+    }
